const el=document.querySelector('#app');
let user=null,data=null,demo=false,publicVillages=[],view='overview',selected=null,filterVillage='',filterStatus='';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=s=>String(s).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const id=n=>`CV-${String(n).padStart(4,'0')}`;
const date=s=>new Date(s.includes('T')?s:s.replace(' ','T')+'Z').toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const badge=s=>`<span class="badge ${esc(s)}">${esc(title(s))}</span>`;
const brand='<a href="#" class="brand"><span class="brandmark" aria-hidden="true"></span>CleanVillage<span class="sr-only"></span></a>';
const roles={citizen:'Resident',manager:'Village manager',admin:'Administrator',staff:'Working staff'};
async function api(url,body){const r=await fetch('/api/'+url,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed.');return d;}
function toast(s){document.querySelector('#toast').textContent=s;setTimeout(()=>document.querySelector('#toast').textContent='',4500);}
async function refresh(){const s=await api('session');user=s.user;demo=s.demo;publicVillages=s.villages||[];if(user)data=await api('data');render();}
const btn=(text,attrs='',secondary=false)=>`<button class="btn${secondary?' secondary':''}" ${attrs}>${text}</button>`;
function landing(){return `<div class="public-site"><div class="civic-bar"><span>COMMUNITY SANITATION & ENVIRONMENTAL CARE</span><span>English <span aria-hidden="true">⌄</span></span></div><header class="topbar">${brand}<nav class="toplinks"><a href="#how">Our approach</a><a href="#care">Community care</a>${btn('Access your portal ↗','data-login')}</nav></header><main><section class="nature-hero"><img class="canopy" src="/assets/green-canopy.jpg" alt="Sunlight filtering through a lush green canopy"><div class="hero-shade"></div><div class="hero-content"><div class="eyebrow"><span class="live-dot"></span> A shared commitment to cleaner villages</div><h1>Small actions.<br><em>Greener futures.</em></h1><p>The place we call home deserves our care.<br>Report a concern. Follow the progress.<br>Help your village thrive.</p><div class="actions">${btn('Report a concern <span>↗</span>','data-login')}${btn('Explore how it works <span>↓</span>','data-how',true)}</div></div><div class="hero-bottom"><span>ROOTED IN COMMUNITY. GROWING TOGETHER.</span><span>01 / A cleaner tomorrow</span></div><div class="hero-side">CLEAN VILLAGE · BETTER LIVING</div></section><section class="service-ribbon"><div class="ribbon-intro"><span class="eyebrow">Your village, connected</span><h2>Care that reaches<br>every corner.</h2></div><a href="#how"><span class="service-no">01</span><div><strong>Report & track</strong><small>From your concern to a verified resolution.</small></div><span class="service-arrow">↗</span></a><a href="#care"><span class="service-no">02</span><div><strong>Local action</strong><small>Village managers. Dedicated area teams.</small></div><span class="service-arrow">↗</span></a><a href="#care"><span class="service-no">03</span><div><strong>Green rewards</strong><small>Recognition for genuine contributions.</small></div><span class="service-arrow">↗</span></a></section><section class="approach-section" id="how"><div class="section-intro"><div><div class="eyebrow">A clear path to a cleaner place</div><h2>Every concern deserves<br><em>to be followed through.</em></h2></div><p>No uncertainty about what happens next. Your report stays connected to the people responsible, from the first photograph to the final verification.</p></div><div class="process-grid"><article><span class="step-index">01 / REPORT</span><h3>It starts with you.</h3><p>Share a photograph and the location of a sanitation issue. Your report reaches the right village.</p><span class="process-line"></span></article><article><span class="step-index">02 / TAKE ACTION</span><h3>Local people. Real work.</h3><p>A village manager reviews your concern and assigns an available team serving that area.</p><span class="process-line"></span></article><article><span class="step-index">03 / VERIFY</span><h3>Progress you can see.</h3><p>Follow status updates and see the team's completion photographs when the work is done.</p><span class="process-line"></span></article></div></section><section class="care-section" id="care"><div class="care-photo"><img src="/assets/green-canopy.jpg" alt="Green woodland in natural light" loading="lazy"><span>OUR SURROUNDINGS. OUR RESPONSIBILITY.</span></div><div class="care-copy"><div class="eyebrow">Built around your community</div><h2>A little care.<br>A lasting <em>difference.</em></h2><p>Cleaner surroundings begin with everyday participation. CleanVillage brings residents, village managers, and sanitation teams into one shared effort.</p><div class="care-facts"><div><strong>Private by design</strong><span>Your complaints are visible only to you and authorised people handling them.</span></div><div><strong>Recognition with purpose</strong><span>Earn 10 coins on verification and 10 more after approved resolution of an eligible complaint.</span></div></div>${btn('Enter your community portal ↗','data-login')}</div></section><section class="closing"><div><div class="eyebrow">The next step is a small one</div><h2>See a problem?<br>Be part of the solution.</h2></div>${btn('Make your first report ↗','data-login')}</section></main><footer class="footer"><div>${brand}<p>Better surroundings begin with us.</p></div><div><span>Community sanitation platform</span><small>Independent college project. Not a government service.</small></div><a href="#">Back to top ↑</a></footer></div>`;}

function login(){el.innerHTML=`<main class="access-layout"><section class="access-story"><div class="access-photo"></div><div class="access-top">${brand}<span>COMMUNITY PORTAL</span></div><div class="access-message"><div class="eyebrow">A place worth caring for.</div><h1>Welcome back<br>to a <em>greener<br>tomorrow.</em></h1><p>Your community. Your contribution.<br>One shared commitment to better surroundings.</p></div><div class="growth-decoration" aria-hidden="true"><i></i><i></i><i></i></div><div class="access-bottom"><span class="live-dot"></span> Rooted in community. Growing together.</div></section><section class="access-form-side"><button class="back" id="back-home">← Back to CleanVillage</button><div class="access-form-wrap"><div class="access-seal" aria-hidden="true">${icon('leaf')}</div><div class="eyebrow">YOUR COMMUNITY STARTS HERE</div><h2>Make yourself<br><em>at home.</em></h2><p class="muted">Sign in to your CleanVillage workspace.</p><form id="login-form"><div class="field"><label for="email">Email address</label><div class="input-with-icon">${icon('mail')}<input id="email" name="email" type="email" autocomplete="username" placeholder="you@example.com" required></div></div><div class="field"><label for="password">Password</label><div class="input-with-icon">${icon('lock')}<input id="password" name="password" type="password" autocomplete="current-password" placeholder="Enter your password" required><button type="button" class="reveal-password" aria-label="Show password" id="show-password">${icon('eye')}</button></div></div><div class="error" role="alert"></div>${btn('Enter your workspace <span>↗</span>','type="submit"')}</form><button class="create-account" id="create-account">New resident? Create an account →</button>${demo?`<details class="demo-access"><summary>Explore the design with a demo account <span>＋</span></summary><p>Choose a role to fill its local test credentials.</p><div class="demo-roles">${[['resident','Resident'],['manager','Manager'],['staff','Working staff'],['admin','Admin']].map(([key,label])=>`<button type="button" data-demo="${key}">${label} ↗</button>`).join('')}</div><small>Test accounts only. Email and mobile services are not connected.</small></details>`:''}<div class="access-assurance">${icon('lock')}<span>Your account opens only the workspace authorised for your role.</span></div></div><div class="access-legal">CleanVillage · Independent community project<span>English</span></div></section></main>`;document.querySelector('#back-home').onclick=render;document.querySelector('#create-account').onclick=register;document.querySelector('#show-password').onclick=e=>{const input=document.querySelector('#password');input.type=input.type==='password'?'text':'password';e.currentTarget.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password');};el.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{document.querySelector('#email').value=b.dataset.demo+'@demo.local';document.querySelector('#password').value='VillageDemo!2026';});document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;await submit(form,async()=>{await api('login',Object.fromEntries(new FormData(form)));view='overview';await refresh();});};}
function register(){el.innerHTML=`<main class="access-layout"><section class="access-story"><div class="access-photo"></div><div class="access-top">${brand}<span>RESIDENT REGISTRATION</span></div><div class="access-message"><div class="eyebrow">Your voice belongs here.</div><h1>Join a cleaner,<br><em>greener village.</em></h1><p>Create one private resident account. You can report supported locations beyond your home village.</p></div></section><section class="access-form-side"><button class="back" id="back-login">← Back to sign in</button><div class="access-form-wrap register-wrap"><div class="eyebrow">CREATE RESIDENT ACCOUNT</div><h2>Begin with<br><em>your community.</em></h2><form id="register-form">${field('Full name','name','text','required maxlength="100"')}${field('Email address','email','email','required autocomplete="email"')}${field('Password','password','password','required minlength="10" autocomplete="new-password"')}<div class="field"><label>Home village</label><select name="village_id">${data?.villages?.map(v=>option(v.id,v.name)).join('')||'<option value="1">Pinapadu</option><option value="2">Burripalem</option>'}</select></div><div class="error"></div>${btn('Create and verify account ↗','type="submit"')}</form><form id="verify-form" hidden>${field('Email address','email','email','required')}${field('Six-digit verification code','code','text','required inputmode="numeric" maxlength="6"')}<p class="demo-code"></p><div class="error"></div>${btn('Verify email ↗','type="submit"')}</form></div></section></main>`;document.querySelector('#back-login').onclick=login;document.querySelector('#register-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{const values=Object.fromEntries(new FormData(form)),result=await api('register',values);form.hidden=true;const verify=document.querySelector('#verify-form');verify.hidden=false;verify.email.value=values.email;if(result.demoCode)verify.querySelector('.demo-code').textContent=`Local demo code: ${result.demoCode}`;});};document.querySelector('#verify-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{await api('verify-email',Object.fromEntries(new FormData(form)));toast('Email verified. You can now sign in.');login();});};}
function icon(name){const paths={camera:'M3 7h4l2-3h6l2 3h4v14H3ZM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',leaf:'M20 4c-8-2-16 2-16 9a7 7 0 0 0 7 7c7 0 11-8 9-16ZM4 20 15 9',mail:'M3 5h18v14H3ZM3 6l9 7 9-7',lock:'M5 10h14v11H5ZM8 10V6a4 4 0 0 1 8 0v4',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',overview:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7',complaints:'M6 3h12v18H6ZM9 8h6M9 12h6M9 16h4',submit:'M12 4v16M4 12h16',coins:'M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0ZM14 8h-3a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4h-3M12 6v12',teams:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM17 3a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-4',notifications:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM9 21h6',check:'M4 12l5 5L20 6',clock:'M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0ZM12 7v5l3 2'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;}
function overview(){const cs=data.complaints,total=cs.length,resolved=cs.filter(c=>c.status==='resolved').length,active=cs.filter(c=>!['resolved','rejected'].includes(c.status)).length,awaiting=cs.filter(c=>c.status==='awaiting_verification').length;const resident=user.role==='citizen',staff=user.role==='staff';const config={citizen:['A better village starts with you.','Every genuine report is a step towards a healthier place to live.','Report a concern','submit'],manager:['Local care. Lasting change.','Coordinate your village teams and keep every concern moving forward.','Review complaints','complaints'],admin:['Every village. One clear view.','Oversee local action and support the people making it happen.','Open complaint register','complaints'],staff:['Good work starts here.','Your assignments, evidence, and next steps in one place.','View assigned work','complaints']}[user.role];const village=data.villages.find(v=>v.id===user.village_id)?.name||'Your community';return `<div class="overview-heading"><div><div class="eyebrow">${user.role==='admin'?'ALL VILLAGES':esc(village)} / ${roles[user.role].toUpperCase()}</div><h2>Welcome back, <em>${esc(user.name.split(' ')[0])}.</em></h2><p>Here’s where things stand in your community.</p></div><div class="today-stamp">${icon('leaf')}<span>COMMUNITY WORKSPACE<br><strong>${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}</strong></span></div></div><div class="overview-top"><section class="action-landscape"><div class="action-landscape-copy"><div class="eyebrow">${resident?'YOUR VOICE MAKES A DIFFERENCE':'PURPOSE IN EVERY ACTION'}</div><h2>${config[0]}</h2><p>${config[1]}</p>${btn(config[2]+' <span>↗</span>',`data-view="${config[3]}"`)}</div><div class="growth-decoration" aria-hidden="true"><i></i><i></i><i></i></div><span class="landscape-label">CLEANVILLAGE / SHARED RESPONSIBILITY</span></section><section class="impact-card"><div class="impact-title"><span>${resident?'YOUR GREEN COINS':'RESOLUTION OVERVIEW'}</span>${icon(resident?'leaf':'check')}</div><strong class="impact-number">${resident?user.coins:resolved}<small>${resident?'coins':'resolved'}</small></strong><p>${resident?'Small contributions add up to a cleaner community.':total?`${resolved} of ${total} visible complaints have approved resolutions.`:'Your resolution summary will grow as work is completed.'}</p><button class="text-action" data-view="${resident?'coins':'complaints'}">${resident?'View coin history':'View complaint progress'} <span>↗</span></button><div class="impact-bottom">${icon(resident?'check':'clock')} ${resident?'10 on verification + 10 on resolution':'Based on actual complaint records'}</div></section></div><div class="metric-grid">${[['complaints','Total complaints',total,'Within your access'],['clock',staff?'Open assignments':'Active complaints',active,'Awaiting completion'],['check','Resolved',resolved,'Completion approved'],['eye','Needs verification',awaiting,'Evidence ready for review']].map(([i,label,value,caption])=>`<article class="metric"><div class="metric-icon">${icon(i)}</div><div><span>${label}</span><strong>${value}</strong><small>${caption}</small></div></article>`).join('')}</div><div class="overview-lower"><div>${complaintTable()}</div><aside class="activity-panel"><div class="panel-head"><h3>Latest activity</h3>${icon('notifications')}</div>${data.notifications.length?data.notifications.slice(0,4).map(n=>`<div class="activity-entry"><i></i><p>${esc(n.message)}<small>${date(n.created)}</small></p></div>`).join(''):`<div class="activity-empty">${icon('leaf')}<h3>A fresh beginning.</h3><p>Your updates will appear here as your community takes action.</p></div>`}<button class="text-action" data-view="notifications">All notifications <span>↗</span></button></aside></div><div class="workspace-note">${icon('lock')}<span>${resident?'Your reports stay private. Only authorised people handling them can access the details.':'Your workspace shows only the records permitted for your role and village.'}</span></div>`;}

function render(){if(!user){el.innerHTML=landing();el.querySelectorAll('[data-login]').forEach(b=>b.onclick=login);el.querySelector('[data-how]').onclick=()=>document.querySelector('#how').scrollIntoView({behavior:'smooth'});return;}
 const nav=portalNav();
 el.innerHTML=`<div class="shell"><aside class="sidebar">${brand}<div class="eyebrow">${roles[user.role]} workspace</div><nav class="nav">${nav.map(([v,i,n])=>`<button data-view="${v}" class="${view===v?'active':''}">${icon(v)}${n}</button>`).join('')}</nav><div class="sidefoot"><strong>${esc(user.name)}</strong>${roles[user.role]}<br><button data-logout>Sign out</button></div></aside><div class="workspace"><header class="workspace-head"><span>Community services / ${esc(view==='detail'?'Complaint details':title(view))}</span><div class="actions"><button class="btn secondary" data-logout>Sign out</button><span class="avatar">${esc(user.name[0])}</span></div></header>${demo?'<div class="demo-label">LOCAL DEVELOPMENT · Seeded test accounts · Email and mobile services are not connected</div>':''}<main class="content">${content()}</main></div></div>`;
 el.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});el.querySelectorAll('[data-logout]').forEach(b=>b.onclick=async()=>{await api('logout',{});user=null;render();});el.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.detail);view='detail';render();});
 document.querySelector('#village-filter')?.addEventListener('change',e=>{filterVillage=e.target.value;render();});document.querySelector('#status-filter')?.addEventListener('change',e=>{filterStatus=e.target.value;render();});
 if(view==='submit'){bindComplaint();bindReportDesign();bindCategorySelect();}if(view==='detail')bindActions();bindModules();
}
function heading(k,h,p,action=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h2>${h}</h2><p>${p}</p></div>${action}</div>`;}
function content(){
 if(view==='overview')return overview();
 if(view==='submit')return complaintForm();if(view==='detail')return detail();
 const modulePage=modulesContent();if(modulePage!==null)return modulePage;
 if(view==='teams')return heading('Local operations','Working teams','Availability updates when work is assigned or completion proof is submitted.')+`<div class="team-grid">${data.teams.map(t=>`<article class="panel"><div class="eyebrow">${esc(data.areas.find(a=>a.id===t.area_id)?.name)}</div><h3>${esc(t.name)}</h3><p>${badge(t.busy?'in_progress':'available')}</p><small>${t.queued} rework assignment${t.queued===1?'':'s'} queued</small></article>`).join('')}</div>`;
 if(view==='notifications')return heading('Stay informed','Notifications','Your latest complaint and work updates.')+`<section class="panel">${data.notifications.length?data.notifications.map(n=>`<article class="notification">${esc(n.message)}<small>${date(n.created)}</small></article>`).join(''):'<div class="empty">You’re all caught up.</div>'}</section>`;
 if(view==='coins')return heading('Green coins','Your contribution counts.',`Current balance: ${user.coins} coins.`)+`<div class="panel table-wrap"><table><thead><tr><th>Reference</th><th>Reason</th><th>Coins</th><th>Date</th></tr></thead><tbody>${data.ledger.map(l=>`<tr><td>${l.complaint_id?id(l.complaint_id):'Reward'}</td><td>${title(l.event)}</td><td>${l.amount>0?'+':''}${l.amount}</td><td>${date(l.created)}</td></tr>`).join('')||'<tr><td colspan="4">Your verified contributions will appear here.</td></tr>'}</tbody></table></div><p class="muted">10 coins are recorded at verification and another 10 after approved resolution. Reward redemptions are deducted immediately.</p>`;
 const cs=data.complaints,active=cs.filter(c=>!['resolved','rejected'].includes(c.status)).length;
 return heading(user.role==='admin'?'All villages':esc(data.villages.find(v=>v.id===user.village_id)?.name||'Your community'),view==='overview'?(user.role==='citizen'?'Your village. Your voice.':'A clear view of your community.'):(user.role==='citizen'?'My complaints':'Complaint management'),user.role==='citizen'?'Report a concern and follow every step towards resolution.':'Review reports, coordinate teams, and verify completed work.',user.role==='citizen'?btn('＋ Report a problem','data-view="submit"'):'')+
 (view==='overview'?`<div class="stats"><div class="stat"><small>Total complaints</small><strong>${cs.length}</strong><small>Within your access</small></div><div class="stat"><small>Active complaints</small><strong>${active}</strong><small>Work still to be completed</small></div><div class="stat"><small>Resolved</small><strong>${cs.filter(c=>c.status==='resolved').length}</strong><small>Completion approved</small></div><div class="stat"><small>${user.role==='citizen'?'Green coins':'Awaiting verification'}</small><strong>${user.role==='citizen'?user.coins:cs.filter(c=>c.status==='awaiting_verification').length}</strong><small>${user.role==='citizen'?'Earned through genuine reports':'Completion evidence submitted'}</small></div></div>`:'')+complaintTable()+reviewPanel();
}
function reviewPanel(){if(!['manager','admin'].includes(user.role)||!data.reviews.length)return '';return `<section class="panel review-panel"><div class="panel-head"><h3>Resident resolution reviews</h3></div>${data.reviews.map(r=>`<article><div><strong>${id(r.complaint_id)} · ${esc(r.resident)}</strong><p>${esc(r.reason)}</p>${r.photo?`<img src="${esc(r.photo)}" alt="Resident review evidence">`:''}</div>${badge(r.status)}${r.status==='pending'?`<form data-module-form="review_decide"><input type="hidden" name="id" value="${r.id}"><div class="actions"><button class="btn" name="decision" value="accept">Reopen for rework</button><button class="btn secondary" name="decision" value="reject">Reject review</button></div><div class="error"></div></form>`:''}</article>`).join('')}</section>`;}
function complaintTable(){const list=data.complaints.filter(c=>(!filterVillage||c.village_id===Number(filterVillage))&&(!filterStatus||c.status===filterStatus));return `<section class="panel"><div class="panel-head"><h3>${user.role==='citizen'?'Your reports':'Complaint register'}</h3><div class="filters"><select id="village-filter" aria-label="Filter by village"><option value="">All visible villages</option>${data.villages.map(v=>`<option value="${v.id}" ${filterVillage==v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select><select id="status-filter" aria-label="Filter by status"><option value="">All statuses</option>${['submitted','verified','assigned','in_progress','awaiting_verification','rework_required','no_issue_reported','resolved','rejected'].map(s=>`<option value="${s}" ${filterStatus===s?'selected':''}>${title(s)}</option>`).join('')}</select></div></div>${!list.length?'<div class="empty"><div class="empty-symbol" aria-hidden="true"><span></span></div><div class="eyebrow">A clear space for progress</div><h3>No reports here yet.</h3><p>As reports arrive, follow their journey<br>from first concern to verified resolution.</p></div>':`<div class="table-wrap"><table><thead><tr><th>Complaint</th><th>Location</th><th>Status</th><th>Priority</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td><small>${id(c.id)} · ${esc(c.category)}</small><strong>${esc(c.title)}</strong></td><td>${esc(c.village)}<small>${esc(c.area)}</small></td><td>${badge(c.status)}</td><td>${esc(c.priority)}</td><td><button class="row-link" data-detail="${c.id}">View →</button></td></tr>`).join('')}</tbody></table></div>`}</section>`;}
function field(label,name,type='text',attrs=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" ${attrs}></div>`;}
function complaintForm(){return heading('A SMALL ACTION. A REAL DIFFERENCE.','Help your village take the next step.','Share what you see. We’ll connect your concern with the people who can help.')+`<div class="report-layout"><form id="complaint-form" class="report-form"><div class="report-progress"><span id="progress-label">Let’s build your report</span><span id="progress-count">0 / 3 sections ready</span><progress id="report-progress" max="3" value="0" aria-label="Report completion"></progress></div><section class="report-section"><header><span class="section-number">01</span><div><span class="section-kicker">THE CONCERN</span><h3>Tell us what needs attention.</h3><p>A few clear details help the right team get started.</p></div>${icon('complaints')}</header><div class="form-grid">${field('Give your report a short title','title','text','required maxlength="140" placeholder="e.g. Overflowing bin near the market"')}<div class="field category-field"><label id="category-label" for="category-toggle">Type of concern</label><input type="hidden" name="category" id="category" value="Garbage dump"><button type="button" id="category-toggle" class="category-toggle" aria-haspopup="listbox" aria-expanded="false" aria-controls="category-options" aria-labelledby="category-label category-current"><span class="category-selected-icon">${icon('complaints')}</span><span id="category-current">Garbage dump</span><svg class="category-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button><div id="category-options" class="category-options" role="listbox" aria-labelledby="category-label" hidden>${[['Garbage dump','complaints','Waste piled up in a public space'],['Overflowing bin','submit','A full bin that needs emptying'],['Blocked drainage','leaf','Water or waste blocking a drain'],['Missed waste collection','clock','A scheduled pickup did not happen'],['Other sanitation issue','complaints','Another concern in your surroundings']].map(([name,symbol,description],i)=>`<button type="button" role="option" tabindex="-1" aria-selected="${i===0}" data-category="${name}"><span class="category-option-icon">${icon(symbol)}</span><span><strong>${name}</strong><small>${description}</small></span><span class="category-check">${icon('check')}</span></button>`).join('')}</div></div><div class="field full"><div class="label-row"><label for="description">What’s happening?</label><span id="description-count">0 / 2000</span></div><textarea name="description" id="description" required maxlength="2000" placeholder="Describe the issue and anything the cleaning team should know…"></textarea></div></div></section><section class="report-section"><header><span class="section-number">02</span><div><span class="section-kicker">THE EVIDENCE</span><h3>A clearer picture helps.</h3><p>Attach one photograph of the issue. Required · up to 2 MB.</p></div>${icon('camera')}</header><label class="photo-drop" id="photo-drop" for="photo"><input id="photo" name="photo" type="file" required accept="image/jpeg,image/png,image/webp"><span class="upload-visual">${icon('submit')}</span><strong id="upload-title">Choose a photograph</strong><span id="upload-hint">or drag and drop it here</span><small>JPG, PNG or WebP · Maximum 2 MB</small><img id="photo-preview" alt="Preview of your complaint photograph" hidden></label><div class="upload-footer"><span id="photo-name">A photo helps your village verify the concern.</span><button type="button" id="remove-photo" hidden>Remove photo</button></div></section><section class="report-section"><header><span class="section-number">03</span><div><span class="section-kicker">THE LOCATION</span><h3>Point us in the right direction.</h3><p>Select where the problem is, even if it isn’t your home village.</p></div>${icon('leaf')}</header><div class="form-grid"><div class="field"><label for="village_id">Village</label><select name="village_id" id="village_id">${data.villages.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select></div><div class="field"><label for="area_id">Area</label><select name="area_id" id="area_id"></select></div><div class="field full"><label for="landmark">Nearby landmark</label><input id="landmark" name="landmark" required maxlength="250" placeholder="e.g. Opposite the school entrance"></div><div class="location-capture full"><div>${icon('leaf')}<span><strong>Capture the exact location</strong><small>Use GPS near the issue, or enter coordinates below.</small></span></div>${btn('Use my location ↗','type="button" id="gps"',true)}<span id="gps-status" role="status"></span></div>${field('Latitude','latitude','number','required step="any" min="-90" max="90" placeholder="e.g. 16.24"')}${field('Longitude','longitude','number','required step="any" min="-180" max="180" placeholder="e.g. 80.64"')}</div></section><div class="report-submit"><div class="error" role="alert"></div><div class="submit-row"><span>${icon('lock')} Only you and authorised staff can see your report.</span>${btn('Send to my village team <span>↗</span>','type="submit"')}</div></div></form><aside class="report-guide"><div class="guide-art">${icon('leaf')}<span>EVERY REPORT MATTERS</span><h3>A cleaner place<br>starts with<br><em>one small step.</em></h3><div class="growth-decoration" aria-hidden="true"><i></i><i></i><i></i></div></div><div class="guide-body"><h4>What happens next?</h4><ol><li><strong>Reviewed locally</strong><p>Your village manager checks your report.</p></li><li><strong>Assigned with care</strong><p>An area team takes up the cleaning work.</p></li><li><strong>Progress you can see</strong><p>Follow updates and completion photographs.</p></li></ol><div class="guide-note">${icon('lock')}<p>Take photographs from a safe spot. Don’t approach hazardous waste.</p></div></div></aside></div>`;}

function detail(){const c=data.complaints.find(c=>c.id===selected);if(!c)return '<p>Complaint unavailable.</p>';const m=['manager','admin'].includes(user.role),s=user.role==='staff';let controls='';
 if(user.role==='citizen'&&c.status==='resolved'&&!data.reviews.some(r=>r.complaint_id===c.id&&r.status==='pending'))controls=`${field('New photograph showing incomplete work','review_photo','file','required accept="image/png,image/jpeg,image/webp"')}${btn('Request a resolution review','data-action="review_request"')}`;
 if(user.role==='citizen'&&c.status==='rejected')controls=`${field('Corrected photograph','resubmit_photo','file','required accept="image/png,image/jpeg,image/webp"')}${btn('Correct and resubmit','data-action="resubmit"')}`;
 if(m&&['submitted','resubmitted'].includes(c.status))controls=`<div class="field"><label for="priority">Priority</label><select id="priority"><option>Normal</option><option>High</option><option>Low</option></select></div>${btn('Verify · +10 coins','data-action="verify"')} ${btn('Reject','data-action="reject"',true)}`;
 if(m&&c.status==='verified')controls=`<div class="field"><label for="team">Available area team</label><select id="team"><option value="">Choose a team</option>${data.teams.filter(t=>t.area_id===c.area_id).map(t=>`<option value="${t.id}" ${t.busy?'disabled':''}>${esc(t.name)}${t.busy?' — Busy':' — Available'}</option>`).join('')}</select></div>${btn('Assign team','data-action="assign"')}`;
 if(s&&['assigned','rework_required'].includes(c.status))controls=btn('Start work','data-action="start"');
 if(s&&c.status==='in_progress')controls=`${field('Proof photograph (required)','proof','file','accept="image/png,image/jpeg,image/webp"')}<div class="actions">${btn('Submit completion','data-action="complete"')}${btn('No issue found','data-action="no_issue"',true)}</div>`;
 if(m&&c.status==='awaiting_verification')controls=`<div class="actions">${btn('Verification complete · +10','data-action="resolve"')}${btn('Return for rework','data-action="rework"',true)}</div>`;
 if(m&&c.status==='no_issue_reported')controls=`<div class="actions">${btn('Confirm rejection · reverse coins','data-action="reject"')}${btn('Return for rework','data-action="rework"',true)}</div>`;
 return `<button class="back" data-view="complaints">← Back to complaints</button>${heading(id(c.id),esc(c.title),`${esc(c.village)} / ${esc(c.area)}`,badge(c.status))}<div class="detail-grid"><div><section class="panel"><img class="photo" src="${esc(c.photo)}" alt="Original complaint photograph"><div class="prose"><div class="eyebrow">The reported issue</div><p>${esc(c.description)}</p><div class="metadata"><div><small>Landmark</small>${esc(c.landmark)}</div><div><small>Location coordinates</small>${c.latitude}, ${c.longitude}</div><div><small>Priority</small>${esc(c.priority)}</div><div><small>Assigned team</small>${esc(c.team||'Awaiting assignment')}</div></div></div></section>${c.proof?`<section class="panel"><div class="panel-head"><h3>Latest work evidence</h3></div><img class="photo" src="${esc(c.proof)}" alt="Work evidence supplied by the assigned team"></section>`:''}${controls?`<section class="panel"><div class="panel-head"><h3>Next action</h3></div><div class="form-body" id="action-form"><div class="field"><label for="note">Notes / reason (required for rejection or rework)</label><textarea id="note" maxlength="2000"></textarea></div>${controls}<div class="error" role="alert"></div></div></section>`:''}</div><section class="panel"><div class="panel-head"><h3>Complaint history</h3></div><div class="timeline">${c.history.map(h=>`<article class="entry"><strong>${title(h.status)}</strong><p>${esc(h.note)}</p><small>${esc(h.actor)} · ${date(h.created)}</small>${h.photo?`<img src="${esc(h.photo)}" alt="Evidence for ${esc(title(h.status))}">`:''}</article>`).join('')}</div></section></div>`;
}
async function submit(form,fn){const buttons=form.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);form.querySelector('.error').textContent='';try{await fn();}catch(e){form.querySelector('.error').textContent=e.message;}finally{buttons.forEach(b=>b.disabled=false);}}
async function imageFile(input){const file=input?.files?.[0];if(!file)throw Error('A photograph is required.');if(file.size>2*1024*1024)throw Error('Choose a photograph smaller than 2 MB.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read this photograph.'));r.readAsDataURL(file);});}
function bindComplaint(){const villages=document.querySelector('#village_id'),areas=document.querySelector('#area_id');const update=()=>areas.innerHTML=data.areas.filter(a=>a.village_id===Number(villages.value)).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('');villages.onchange=update;update();document.querySelector('#gps').onclick=()=>{const status=document.querySelector('#gps-status');if(!navigator.geolocation){status.textContent='GPS is unavailable. Enter coordinates manually.';return;}status.textContent='Finding your location…';navigator.geolocation.getCurrentPosition(p=>{document.querySelector('#latitude').value=p.coords.latitude;document.querySelector('#longitude').value=p.coords.longitude;status.textContent='Location captured. Confirm that this is the issue’s location.';},()=>status.textContent='Location could not be obtained. Enter coordinates manually.',{timeout:15000,enableHighAccuracy:true});};document.querySelector('#complaint-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{const values=Object.fromEntries(new FormData(form));values.photo=await imageFile(form.querySelector('#photo'));await api('complaints',values);view='complaints';await refresh();toast('Complaint submitted to the village.');});};}
function bindActions(){el.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>submit(document.querySelector('#action-form'),async()=>{const c=data.complaints.find(c=>c.id===selected),action=b.dataset.action;if(action==='review_request'){await api('modules/action',{action,complaint_id:c.id,reason:document.querySelector('#note')?.value,photo:await imageFile(document.querySelector('#review_photo'))});await refresh();toast('Review request sent.');return;}const payload={action,expectedStatus:c.status,note:document.querySelector('#note')?.value,priority:document.querySelector('#priority')?.value,team_id:document.querySelector('#team')?.value};if(['complete','no_issue'].includes(action))payload.proof=await imageFile(document.querySelector('#proof'));if(action==='resubmit')payload.proof=await imageFile(document.querySelector('#resubmit_photo'));await api(`complaints/${c.id}/action`,payload);await refresh();toast('Update saved.');}));}
function portalNav(){const common=[['overview','overview','Overview'],['complaints','complaints',user.role==='citizen'?'My complaints':'Complaints']];const byRole={citizen:[['submit','submit','Report a problem'],['coins','coins','Coins'],['rewards','leaf','Rewards'],['community','leaf','Village services'],['offers','notifications','Role offers']],staff:[['teams','teams','My team'],['collections','clock','Collections'],['deliveries','leaf','Deliveries'],['community','leaf','Village services']],manager:[['teams','teams','Team status'],['people','notifications','Staff management'],['collections','clock','Schedules'],['deliveries','leaf','Reward delivery'],['community','leaf','Community'],['reports','overview','Reports']],admin:[['people','teams','Roles & approvals'],['rewards','leaf','Reward catalogue'],['collections','clock','Schedules'],['deliveries','leaf','Reward dispatch'],['community','leaf','Community'],['reports','overview','Reports']]};return [...common,...byRole[user.role],['notifications','notifications','Notifications']];}
const option=(value,label,selected=false)=>`<option value="${value}" ${selected?'selected':''}>${esc(label)}</option>`;
function miniForm(action,inner,label='Save'){return `<form class="module-form panel" data-module-form="${action}"><div class="form-grid">${inner}</div><div class="error" role="alert"></div>${btn(label+' <span>↗</span>','type="submit"')}</form>`;}
function statusTrail(status){const steps=['requested','dispatched_to_village','received_by_manager','out_for_delivery','delivered'],at=Math.max(0,steps.indexOf(status));return `<div class="status-trail">${steps.map((s,i)=>`<span class="${i<=at?'done':''}"><i></i>${title(s)}</span>`).join('')}</div>`;}
function modulesContent(){
 if(view==='offers'&&user.role==='citizen')return heading('ROLE INVITATIONS','Offers to serve your village','Accepting a manager or working-staff role disables personal complaints, coins and rewards until you return to normal-user status.')+`<div class="module-grid">${data.invites.map(i=>`<article class="module-card"><div>${badge(i.status)}<h3>${title(i.role)} invitation</h3><p>Sent by ${esc(i.inviter)} for ${esc(data.villages.find(v=>v.id===i.village_id)?.name)}.</p></div>${i.status==='pending'?`<form data-module-form="invite_response"><input type="hidden" name="id" value="${i.id}"><div class="field"><label>Original mobile number</label><input name="mobile" required placeholder="+91 98765 43210"></div><div class="actions"><button class="btn" name="decision" value="accept">Accept</button><button class="btn secondary" name="decision" value="decline">Decline</button></div><div class="error"></div></form>`:''}</article>`).join('')||'<div class="empty panel">No role invitations are waiting.</div>'}</div>`;
 if(view==='rewards')return rewardsPage();
 if(view==='deliveries')return deliveriesPage();
 if(view==='collections')return collectionsPage();
 if(view==='community')return communityPage()+residentSchedules();
 if(view==='people')return peoplePage()+(user.role==='admin'?managerRoster():'');
 if(view==='reports')return reportsPage();
 return null;
}
function rewardsPage(){const cards=`<div class="reward-grid">${data.rewards.map(r=>`<article class="reward-card"><div class="reward-art">${icon('leaf')}<span>${r.stock} available</span></div><div><div class="eyebrow">GREEN REWARD</div><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p><strong>${r.cost} <small>coins</small></strong>${user.role==='citizen'?`<button class="btn" data-module-click="redeem" data-reward_id="${r.id}" ${user.coins<r.cost||!r.stock?'disabled':''}>Redeem reward ↗</button>`:''}</div></article>`).join('')}</div>`;if(user.role!=='admin')return heading('GREEN REWARDS','Small actions, useful rewards.',`Your available balance is ${user.coins} coins. Every confirmed order will be fulfilled.`)+cards+`<section class="panel delivery-history"><h3>Your reward orders</h3>${data.redemptions.map(d=>`<article><strong>${esc(d.reward)}</strong>${statusTrail(d.status)}<small>Requested ${date(d.created)}</small></article>`).join('')||'<p>No reward orders yet.</p>'}</section>`;return heading('REWARD CATALOGUE','Set the value of community recognition.','Create rewards, coin costs and available stock. Orders already placed remain valid.')+miniForm('reward_save',`${field('Reward name','name','text','required maxlength="100"')}${field('Coin cost','cost','number','required min="1"')}${field('Stock','stock','number','required min="0"')}<div class="field full"><label>Description</label><textarea name="description" required maxlength="500"></textarea></div>`,'Add reward')+cards;}
function deliveriesPage(){const roleHelp={citizen:'Track every handover from the admin to your doorstep.',admin:'Dispatch requested rewards to the correct village.',manager:'Receive village parcels and assign an area team for delivery.',staff:'Deliver assigned rewards and confirm the user’s private code.'}[user.role];return heading('REWARD FULFILMENT','Every redeemed reward reaches its owner.',roleHelp)+`<div class="delivery-list">${data.redemptions.map(d=>`<article class="panel delivery-item"><div><div class="eyebrow">ORDER #${d.id}</div><h3>${esc(d.reward)}</h3><p>${esc(d.recipient||'Your order')}${d.village?' · '+esc(d.village):''}${d.team?' · '+esc(d.team):''}</p>${d.address?`<small>${esc(d.address)} · ${esc(d.contact)}</small>`:''}</div>${statusTrail(d.status)}${user.role==='admin'&&d.status==='requested'?`<button class="btn" data-module-click="redemption_update" data-id="${d.id}">Dispatch to village</button>`:''}${user.role==='manager'&&d.status==='dispatched_to_village'?`<button class="btn" data-module-click="redemption_update" data-id="${d.id}">Confirm received</button>`:''}${user.role==='manager'&&d.status==='received_by_manager'?`<form data-module-form="redemption_update"><input type="hidden" name="id" value="${d.id}"><div class="field"><label>Area delivery team</label><select name="team_id" required><option value="">Choose team</option>${data.teams.filter(t=>!d.area_id||t.area_id===d.area_id).map(t=>option(t.id,t.name)).join('')}</select></div><div class="error"></div><button class="btn">Send out for delivery</button></form>`:''}${user.role==='staff'&&d.status==='out_for_delivery'?`<form data-module-form="redemption_update"><input type="hidden" name="id" value="${d.id}">${field('User delivery code','code','text','required inputmode="numeric"')}<div class="error"></div><button class="btn">Confirm delivered</button></form>`:''}</article>`).join('')||'<div class="empty panel">No reward deliveries in this workspace.</div>'}</div>`;}
function collectionsPage(){const canManage=['manager','admin'].includes(user.role);const areas=user.role==='admin'?data.areas:data.areas.filter(a=>a.village_id===user.village_id);return heading('WASTE COLLECTION','Reliable routines, visible follow-through.',canManage?'Publish area schedules and arrange replacements when a collection is missed.':'Report each scheduled collection as completed or missed for your team area.')+(canManage?miniForm('schedule_save',`${user.role==='admin'?`<div class="field"><label>Village</label><select name="village_id" data-village-select>${data.villages.map(v=>option(v.id,v.name)).join('')}</select></div>`:''}<div class="field"><label>Area</label><select name="area_id" required>${areas.map(a=>option(a.id,a.name)).join('')}</select></div><div class="field"><label>Day</label><select name="weekday">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(d=>option(d,d)).join('')}</select></div>${field('Collection time','collection_time','time','required')}`,'Publish schedule'):'')+`<div class="schedule-grid">${data.schedules.map(s=>`<article class="schedule-card"><div class="schedule-day">${esc(s.weekday.slice(0,3).toUpperCase())}<strong>${esc(s.collection_time)}</strong></div><div><h3>${esc(s.area)}</h3><p>${esc(s.village)} · ${s.latest_status?title(s.latest_status):'Awaiting today’s report'}</p>${s.latest_reason?`<small>Reason: ${esc(s.latest_reason)}</small>`:''}${s.replacement_time?`<div class="replacement">Replacement: ${esc(s.replacement_time)}</div>`:''}</div>${user.role==='staff'?`<form data-module-form="collection_update"><input type="hidden" name="schedule_id" value="${s.id}">${field('Service date','service_date','date','required')}<div class="field"><label>Result</label><select name="status"><option value="completed">Completed</option><option value="missed">Missed</option></select></div>${field('Reason if missed','reason')}<div class="error"></div><button class="btn">Submit report</button></form>`:''}${canManage&&s.latest_status==='missed'&&!s.replacement_time?`<form data-module-form="reschedule"><input type="hidden" name="schedule_id" value="${s.id}">${field('Replacement date and time','replacement_time','datetime-local','required')}<div class="error"></div><button class="btn">Set replacement</button></form>`:''}</article>`).join('')||'<div class="empty panel">No collection schedules published yet.</div>'}</div>`;}
function communityPage(){const canPublish=['manager','admin'].includes(user.role);return heading('COMMUNITY CARE','Knowledge and action, in one place.','View sanitation guidance and join village cleanliness drives. Drives do not award coins.')+(canPublish?`<div class="community-compose">${miniForm('post_create',`${user.role==='admin'?`<div class="field"><label>Audience</label><select name="village_id"><option value="">All villages</option>${data.villages.map(v=>option(v.id,v.name)).join('')}</select></div>`:''}${field('Awareness title','title','text','required maxlength="140"')}<div class="field full"><label>Guidance</label><textarea name="body" required></textarea></div>`,'Publish guidance')}${miniForm('event_create',`${user.role==='admin'?`<div class="field"><label>Village</label><select name="village_id">${data.villages.map(v=>option(v.id,v.name)).join('')}</select></div>`:''}<div class="field"><label>Area</label><select name="area_id">${data.areas.filter(a=>user.role==='admin'||a.village_id===user.village_id).map(a=>option(a.id,a.name)).join('')}</select></div>${field('Drive title','title','text','required')}${field('Date and time','event_time','datetime-local','required')}${field('Meeting point','meeting_point','text','required')}<div class="field full"><label>Description</label><textarea name="description" required></textarea></div>`,'Create drive')}</div>`:'')+`<div class="community-grid"><section><div class="eyebrow">AWARENESS</div>${data.posts.map(p=>`<article class="story-card"><span>${esc(p.village||'All villages')}</span><h3>${esc(p.title)}</h3><p>${esc(p.body)}</p><small>By ${esc(p.author)} · ${date(p.created)}</small></article>`).join('')}</section><section><div class="eyebrow">UPCOMING DRIVES</div>${data.events.map(e=>`<article class="event-card"><time>${new Date(e.event_time).toLocaleDateString('en-IN',{day:'2-digit',month:'short'})}</time><div><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p><small>${esc(e.area)} · ${esc(e.meeting_point)} · ${e.registrations} registered</small></div>${user.role==='citizen'&&!e.registered?`<button class="btn secondary" data-module-click="event_register" data-event_id="${e.id}">Register</button>`:e.registered?badge('registered'):''}</article>`).join('')||'<div class="empty panel">No drives scheduled.</div>'}</section></div>`;}
function residentSchedules(){if(!data.schedules.length)return '';return `<section class="panel public-schedules"><div class="panel-head"><div><div class="eyebrow">AREA COLLECTION CALENDAR</div><h3>Waste collection timings</h3></div></div><div class="schedule-strip">${data.schedules.map(s=>`<article><span>${esc(s.weekday)}</span><strong>${esc(s.collection_time)}</strong><small>${esc(s.area)} · ${esc(s.village)}</small>${s.replacement_time?`<em>Replacement ${esc(s.replacement_time)}</em>`:''}</article>`).join('')}</div></section>`;}
function peoplePage(){if(user.role==='manager'){const citizens=data.people.filter(p=>p.role==='citizen'),staff=data.people.filter(p=>p.role==='staff');return heading('PEOPLE & TEAMS','Build capable area teams.','Invite registered residents, organise accepted staff, and request role removal with admin approval.')+`<div class="people-layout">${miniForm('invite',`<input type="hidden" name="role" value="staff"><div class="field full"><label>Eligible registered resident</label><select name="target_id" required><option value="">Choose resident</option>${citizens.map(p=>option(p.id,`${p.name} · ${p.email}`)).join('')}</select></div>`,'Send staff offer')}${miniForm('team_create',`${field('Team name','name','text','required')}<div class="field"><label>Service area</label><select name="area_id">${data.areas.filter(a=>a.village_id===user.village_id).map(a=>option(a.id,a.name)).join('')}</select></div>`,'Create team')}</div><div class="people-table panel"><h3>Working staff</h3>${staff.map(p=>`<article><div><strong>${esc(p.name)}</strong><small>${esc(p.email)} · ${p.mobile?esc(p.mobile):'Mobile pending'}</small></div><form data-module-form="team_member"><input type="hidden" name="staff_id" value="${p.id}"><select name="team_id"><option value="">Not assigned</option>${data.teams.map(t=>option(t.id,t.name,t.id===p.team_id)).join('')}</select><div class="error"></div><button class="btn secondary">Update team</button></form><form data-module-form="removal_request"><input type="hidden" name="staff_id" value="${p.id}"><input name="reason" required placeholder="Reason for role removal"><div class="error"></div><button class="row-link">Request role removal</button></form></article>`).join('')||'<div class="empty">No working staff accepted yet.</div>'}</div><section class="panel"><h3>Removal requests</h3>${data.removals.map(r=>`<article class="request-row"><span>${esc(r.staff)}</span>${badge(r.status)}${r.status==='approved'?`<button class="btn" data-module-click="removal_execute" data-id="${r.id}">Complete removal</button>`:''}</article>`).join('')||'<p>No role-removal requests.</p>'}</section>`;}
 const citizens=data.people.filter(p=>p.role==='citizen');return heading('ROLE OVERSIGHT','Trusted access, accountable decisions.','Select village managers and decide staff-role removal requests submitted by managers.')+miniForm('invite',`<input type="hidden" name="role" value="manager"><div class="field"><label>Registered resident</label><select name="target_id" required><option value="">Choose resident</option>${citizens.map(p=>option(p.id,`${p.name} · ${p.email}`)).join('')}</select></div><div class="field"><label>Manager village</label><select name="village_id">${data.villages.map(v=>option(v.id,v.name)).join('')}</select></div>`,'Send manager offer')+`<section class="panel approvals"><h3>Staff-role removal approvals</h3>${data.removals.map(r=>`<article><div><strong>${esc(r.staff)}</strong><p>${esc(r.reason)}</p><small>Requested by ${esc(r.manager)} · ${date(r.created)}</small></div>${badge(r.status)}${r.status==='pending'?`<form data-module-form="removal_decide"><input type="hidden" name="id" value="${r.id}"><input name="note" placeholder="Admin note (optional)"><div class="actions"><button class="btn" name="decision" value="approve">Approve</button><button class="btn secondary" name="decision" value="reject">Reject</button></div><div class="error"></div></form>`:''}</article>`).join('')||'<div class="empty">No pending decisions.</div>'}</section>`;}
function reportsPage(){const total=data.complaints.length,resolved=data.complaints.filter(c=>c.status==='resolved').length,missed=data.schedules.filter(s=>s.latest_status==='missed').length;return heading('MONTHLY REPORTS','Turn service records into decisions.','The report respects your village access. Download the same live figures for review and college documentation.')+`<div class="report-metrics"><article><span>Complaints</span><strong>${total}</strong></article><article><span>Resolved</span><strong>${resolved}</strong></article><article><span>Resolution rate</span><strong>${total?Math.round(resolved/total*100):0}%</strong></article><article><span>Missed collections</span><strong>${missed}</strong></article><article><span>Rewards in delivery</span><strong>${data.redemptions.filter(d=>d.status!=='delivered').length}</strong></article><article><span>Community drives</span><strong>${data.events.length}</strong></article></div><section class="panel report-download"><div><h3>Download operational report</h3><p>Includes complaint, collection, reward and community activity summaries.</p></div><div class="actions"><a class="btn" href="/api/export?format=pdf">Download PDF</a><a class="btn secondary" href="/api/export?format=xls">Download Excel</a></div></section>${user.role==='admin'?miniForm('reminder_settings',`${field('Working day starts','start','time',`required value="${data.settings.working_start||''}"`)}${field('Working day ends','end','time',`required value="${data.settings.working_end||''}"`)}<p class="full muted">Once saved, unassigned complaints trigger manager and admin reminders every three hours, seven days a week, only inside these hours.</p>`,'Save reminder hours'):''}`;}
function managerRoster(){const managers=data.people.filter(p=>p.role==='manager');return `<section class="panel manager-roster"><div class="panel-head"><h3>Current village managers</h3></div>${managers.map(m=>`<article><div><strong>${esc(m.name)}</strong><small>${esc(m.email)} · ${esc(data.villages.find(v=>v.id===m.village_id)?.name||'Village')}</small></div><form data-module-form="remove_manager"><input type="hidden" name="id" value="${m.id}"><input name="reason" required placeholder="Reason for removal"><div class="error"></div><button class="btn secondary">Return to normal user</button></form></article>`).join('')||'<div class="empty">No managers appointed.</div>'}</section><div class="people-layout location-admin">${miniForm('location_save',`<input type="hidden" name="kind" value="village">${field('New supported village','name','text','required')}`,'Add village')}${miniForm('location_save',`<input type="hidden" name="kind" value="area"><div class="field"><label>Village</label><select name="village_id">${data.villages.map(v=>option(v.id,v.name)).join('')}</select></div>${field('New area','name','text','required')}`,'Add area')}</div>`;}
function bindModules(){
 document.querySelectorAll('[data-module-form]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const submitter=e.submitter;submit(form,async()=>{const payload=Object.fromEntries(new FormData(form));payload.action=form.dataset.moduleForm;if(submitter?.name)payload[submitter.name]=submitter.value;await api('modules/action',payload);await refresh();toast('Saved successfully.');});});
 document.querySelectorAll('[data-module-click]').forEach(button=>button.onclick=async()=>{if(button.dataset.moduleClick==='redeem'){openRedemption(button.dataset.reward_id);return;}button.disabled=true;try{const payload={action:button.dataset.moduleClick};for(const [key,value] of Object.entries(button.dataset))if(key!=='moduleClick')payload[key]=value;await api('modules/action',payload);await refresh();toast('Update saved.');}catch(e){toast(e.message);}finally{button.disabled=false;}});
}
function openRedemption(rewardId){const reward=data.rewards.find(r=>r.id===Number(rewardId)),areas=data.areas.filter(a=>a.village_id===user.village_id);const layer=document.createElement('div');layer.className='modal-layer';layer.innerHTML=`<form class="modal-card" data-module-form="redeem"><button type="button" class="modal-close" aria-label="Close">×</button><div class="eyebrow">CONFIRM REWARD DELIVERY</div><h2>${esc(reward.name)}</h2><p>${reward.cost} coins will be deducted now. This confirmed order will be fulfilled.</p><input type="hidden" name="reward_id" value="${reward.id}"><div class="field"><label>Delivery area</label><select name="area_id" required>${areas.map(a=>option(a.id,a.name)).join('')}</select></div>${field('Full delivery address','address','text','required maxlength="300"')}${field('Contact number','contact','tel','required maxlength="20"')}<div class="error"></div>${btn('Confirm redemption ↗','type="submit"')}</form>`;document.body.append(layer);layer.querySelector('.modal-close').onclick=()=>layer.remove();layer.onclick=e=>{if(e.target===layer)layer.remove();};const form=layer.querySelector('form');form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{const payload={...Object.fromEntries(new FormData(form)),action:'redeem'};await api('modules/action',payload);layer.remove();await refresh();toast('Reward requested. Check notifications for your private delivery code.');});};}
refresh().catch(e=>{el.innerHTML='<div class="loading">The application could not connect to its server. Please refresh.</div>';toast(e.message);});

function bindReportDesign(){const form=document.querySelector('#complaint-form'),photo=form.querySelector('#photo'),drop=form.querySelector('#photo-drop'),preview=form.querySelector('#photo-preview');let previewUrl=null;const update=()=>{const done=[!!(form.elements.namedItem('title').value.trim()&&form.description.value.trim()),!!photo.files.length,!!(form.landmark.value.trim()&&form.latitude.value!==''&&form.longitude.value!=='')];document.querySelector('#progress-count').textContent=`${done.filter(Boolean).length} / 3 sections ready`;document.querySelector('#report-progress').value=done.filter(Boolean).length;document.querySelector('#progress-label').textContent=done.every(Boolean)?'Ready for your final check':'Let’s build your report';document.querySelector('#description-count').textContent=`${form.description.value.length} / 2000`;form.querySelectorAll('.report-section').forEach((section,i)=>section.classList.toggle('section-ready',done[i]));};const show=()=>{if(previewUrl)URL.revokeObjectURL(previewUrl);const file=photo.files[0];if(file&&(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>2*1024*1024)){photo.value='';toast('Choose a JPG, PNG or WebP photograph smaller than 2 MB.');return show();}preview.hidden=!file;drop.classList.toggle('has-photo',!!file);document.querySelector('#remove-photo').hidden=!file;if(file){const reader=new FileReader();reader.onload=()=>{preview.src=reader.result;};reader.readAsDataURL(file);document.querySelector('#photo-name').textContent=file.name;document.querySelector('#upload-title').textContent='Choose a different photograph';}else{preview.removeAttribute('src');document.querySelector('#photo-name').textContent='A photo helps your village verify the concern.';document.querySelector('#upload-title').textContent='Choose a photograph';}update();};photo.addEventListener('change',show);form.addEventListener('input',update);form.addEventListener('change',update);document.querySelector('#remove-photo').onclick=()=>{photo.value='';show();};for(const event of ['dragenter','dragover'])drop.addEventListener(event,e=>{e.preventDefault();drop.classList.add('drag-over');});for(const event of ['dragleave','drop'])drop.addEventListener(event,e=>{e.preventDefault();drop.classList.remove('drag-over');});drop.addEventListener('drop',e=>{if(!e.dataTransfer.files.length)return;const transfer=new DataTransfer();transfer.items.add(e.dataTransfer.files[0]);photo.files=transfer.files;show();});new MutationObserver(update).observe(document.querySelector('#gps-status'),{childList:true});update();}

function bindCategorySelect(){const trigger=document.querySelector('#category-toggle'),list=document.querySelector('#category-options'),field=document.querySelector('#category'),options=[...list.querySelectorAll('[role="option"]')];let current=0;function close(focus=false){trigger.closest('.report-section').classList.remove('category-open');list.hidden=true;trigger.setAttribute('aria-expanded','false');if(focus)trigger.focus();}function open(index=current){trigger.closest('.report-section').classList.add('category-open');list.hidden=false;trigger.setAttribute('aria-expanded','true');options[index].focus();}function select(index){current=index;field.value=options[index].dataset.category;document.querySelector('#category-current').textContent=field.value;trigger.querySelector('.category-selected-icon').innerHTML=options[index].querySelector('.category-option-icon').innerHTML;options.forEach((o,i)=>o.setAttribute('aria-selected',String(i===index)));field.dispatchEvent(new Event('change',{bubbles:true}));close(true);}trigger.onclick=()=>list.hidden?open():close();trigger.onkeydown=e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();open(e.key==='Home'?0:e.key==='End'?options.length-1:current);}};options.forEach((option,index)=>{option.onclick=()=>select(index);option.onkeydown=e=>{let next=index;if(e.key==='ArrowDown')next=(index+1)%options.length;else if(e.key==='ArrowUp')next=(index-1+options.length)%options.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=options.length-1;else if(e.key==='Escape'){e.preventDefault();close(true);return;}else if(e.key==='Tab'){close();return;}else if(e.key.length===1&&/[a-z]/i.test(e.key)){const match=options.findIndex((o,i)=>i!==index&&o.dataset.category.toLowerCase().startsWith(e.key.toLowerCase()));if(match>=0)next=match;else return;}else return;e.preventDefault();options[next].focus();};});const container=trigger.closest('.category-field');container.addEventListener('focusout',e=>{if(!container.contains(e.relatedTarget))close();});const outside=e=>{if(!container.isConnected){document.removeEventListener('pointerdown',outside);return;}if(!container.contains(e.target))close();};document.addEventListener('pointerdown',outside);}
